          "@type": "Question",
          "name": "What subjects are on the ATI TEAS?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The ATI TEAS includes Reading, Mathematics, Science, and English and Language Usage. NursingMocks organizes practice around those four areas so you can work by subject."
          }
        },
        {
          "@type": "Question",
          "name": "How many questions are on the ATI TEAS?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The official ATI TEAS Version 7 exam has 170 total questions: 150 scored questions and 20 unscored pretest questions."
          }
        },
        {
          "@type": "Question",
          "name": "How long is the ATI TEAS?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The official exam allocates 209 minutes across four timed sections: 55 minutes for Reading, 57 minutes for Math, 60 minutes for Science, and 37 minutes for English and Language Usage."
          }
        },
        {
          "@type": "Question",
          "name": "Should I start with a full practice test or one subject?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Start with one subject if you already know what needs work. Use full practice when you want to check pacing, stamina, and performance across the full exam."
          }
        },
        {
          "@type": "Question",
          "name": "Which subject should I practice first?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Start with the section that shows the clearest weakness, the least recent practice, or the most repeated mistake pattern. If you do not know yet, sample each subject once and compare."
          }
        },
        {
          "@type": "Question",
          "name": "Are NursingMocks questions official ATI questions?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. NursingMocks is an independent practice resource. It does not provide official ATI questions and does not claim affiliation, authorization, or endorsement from ATI."
          }
        },
        {
          "@type": "Question",
          "name": "How should I use my practice results?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Use the results to choose your next set. Look for the mistake pattern behind the score: source support in Reading, setup or units in Math, concept or evidence in Science, and convention or revision in English."
          }
        }
      ],
      "inLanguage": "en-US"
    }
  ]
