          "@type": "Question",
          "name": "How many questions are in ATI TEAS Math?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "The ATI TEAS Math section includes 38 total questions. ATI identifies 34 Math questions as scored and 4 questions as unscored, so treat every question seriously during practice and on the official exam."
          }
        },
