          "@type": "Question",
          "name": "How should you use your Math practice results?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Group missed questions by cause. If setup errors repeat, work on translating word problems. If unit errors repeat, review conversions and labels. Let the pattern choose the next practice activity."
          }
        }
